function sampleVector(size, seed) {
  var entropy = new Entropy(seed)
  return entropy.bytes(size)
}

function equalBytes(a, b) {
  if (!a || !b || a.length !== b.length) return false
  for (var i = 0; i < a.length; i++) if ((a[i] & 255) !== (b[i] & 255)) return false
  return true
}

function say(line) {
  if (typeof console !== 'undefined' && console && typeof console.log === 'function') console.log(line)
}

function runProbes(context) {
  var results = []
  for (var i = 0; i < PROBES.length; i++) {
    var probe = PROBES[i]
    var outcome
    try {
      outcome = probe.fn(context)
    } catch (error) {
      outcome = { status: 'error', detail: String(error && error.message ? error.message : error), signal: false }
    }
    results.push({
      id: probe.id,
      group: probe.group,
      weight: probe.weight,
      status: outcome.status,
      detail: outcome.detail,
      signal: outcome.signal === true
    })
  }
  return results
}

function tableIsBijective(tables) {
  var bad = 0
  for (var t = 0; t < tables.length; t++) {
    var seen = new Uint8Array(256)
    var table = tables[t]
    for (var i = 0; i < 256; i++) {
      if (seen[table[i] & 255]) {
        bad++
        break
      }
      seen[table[i] & 255] = 1
    }
  }
  return bad === 0
}

function coreSelfTest() {
  var context = buildContext(BUILD_SEED)
  var probes = runProbes(context)

  check('flavor-declared', typeof FLAVOR === 'string' && FLAVOR.length > 0, FLAVOR)
  check('instance-entropy', INSTANCE_SEED !== BUILD_SEED, 'seed=' + (INSTANCE_SEED >>> 0).toString(16))

  var sliceHex = POOL.slice(0, 8192)
  var sliceBytes = hexToBytes(sliceHex)
  var slicePlain = POOL_LAYERS.decode(sliceBytes)
  var reencoded = bytesToHex(POOL_LAYERS.encode(slicePlain))
  check('pool-layer-inverse', reencoded === sliceHex, 'slice=' + (sliceHex.length >> 1) + 'B')
  var poolDigestValue = poolDigest(POOL)
  check('pool-digest-scan', poolDigestValue !== 0, 'digest=' + (poolDigestValue >>> 0).toString(16) + ' pool=' + (POOL.length >> 1) + 'B')

  var vector = sampleVector(32, BUILD_SEED ^ 0x51)
  var radix = new Radix64Codec(mix32(BUILD_SEED, 1))
  var radixText = radix.encode(vector)
  check('encoding-radix64', equalBytes(radix.decode(radixText), vector), 'len=' + radixText.length + ' alphabet=' + radix.alphabet.slice(0, 8))
  var target = radixText[12]
  var tampered = radixText.slice(0, 12) + (target === 'A' ? 'B' : 'A') + radixText.slice(13)
  var rejected = false
  try {
    radix.decode(tampered)
  } catch (error) {
    rejected = true
  }
  check('encoding-radix64-tamper', rejected, 'tamper rejected')

  var bitlane = new BitLaneCodec(mix32(BUILD_SEED, 2))
  var lanes = bitlane.encode(vector)
  var lanesBack = bitlane.decode(lanes).slice(0, vector.length)
  check('encoding-bitlane', equalBytes(lanesBack, vector), 'lanes=' + lanes.length)

  var glyph = new GlyphCodec(mix32(BUILD_SEED, 3))
  var glyphText = glyph.encode(vector)
  check('encoding-glyph', equalBytes(glyph.decode(glyphText), vector), 'glyphs=' + glyphText.length + ' plane=' + glyph.plane.toString(16))

  var spn = new SpnCipher(mix32(BUILD_SEED, 4), 12)
  var feistel = new FeistelCipher(mix32(BUILD_SEED, 5), 16)
  var arx = new ArxCipher(mix32(BUILD_SEED, 6), 8)
  var arxMirror = new ArxCipher(mix32(BUILD_SEED, 6), 8)
  check('cipher-spn', equalBytes(openBlocks(spn, sealBlocks(spn, vector, 16), 16), vector), 'rounds=' + spn.rounds + ' matrix=invertible')
  check('cipher-feistel', equalBytes(openBlocks(feistel, sealBlocks(feistel, vector, 8), 8), vector), 'rounds=' + feistel.rounds)
  check('cipher-arx', equalBytes(arxMirror.cryptBytes(arx.cryptBytes(vector)), vector), 'fresh stream mirrors keystream rounds=' + arx.rounds)

  var wbSpn = new WhiteboxSpn(SPN_MATERIAL, mix32(BUILD_SEED, 7), SPN_ROUNDS)
  var wbFeistel = new WhiteboxFeistel(FEISTEL_MATERIAL, mix32(BUILD_SEED, 8), FEISTEL_ROUNDS)
  var wbArx = new WhiteboxArx(ARX_MATERIAL, mix32(BUILD_SEED, 9), ARX_ROUNDS)
  check('whitebox-spn-roundtrip', equalBytes(openBlocks(wbSpn, sealBlocks(wbSpn, vector, 16), 16), vector), 'rounds=' + wbSpn.rounds + ' material=' + wbSpn.cursor + 'B')
  check('whitebox-spn-bijection', tableIsBijective(wbSpn.tables[0]), 'round0 tables bijective')
  check('whitebox-spn-material', wbSpn.cursor === SPN_MATERIAL.length, 'consumed=' + wbSpn.cursor + '/' + SPN_MATERIAL.length)
  check('whitebox-feistel-roundtrip', equalBytes(openBlocks(wbFeistel, sealBlocks(wbFeistel, vector, 8), 8), vector), 'rounds=' + wbFeistel.rounds + ' material=' + wbFeistel.cursor + 'B')
  check('whitebox-feistel-tables', wbFeistel.cursor === FEISTEL_MATERIAL.length, 'consumed=' + wbFeistel.cursor + '/' + FEISTEL_MATERIAL.length)
  check('whitebox-arx-roundtrip', equalBytes(openBlocks(wbArx, sealBlocks(wbArx, vector, 16), 16), vector), 'rounds=' + wbArx.rounds + ' material=' + wbArx.cursor + 'B')
  check('whitebox-arx-sbox', tableIsBijective(wbArx.sbox), 'round sboxes bijective')
  check('whitebox-arx-material', wbArx.cursor === ARX_MATERIAL.length, 'consumed=' + wbArx.cursor + '/' + ARX_MATERIAL.length)
  check('whitebox-implicit-key', wbSpn.keyTag !== wbFeistel.keyTag && wbFeistel.keyTag !== wbArx.keyTag && wbArx.keyTag !== 0, 'implicit tags=' + (wbSpn.keyTag >>> 0).toString(16) + ',' + (wbFeistel.keyTag >>> 0).toString(16) + ',' + (wbArx.keyTag >>> 0).toString(16))

  var vmSeed = mix32(BUILD_SEED, 10)
  var innerSeed = mix32(BUILD_SEED, 11)
  var vm = new FortressVm(vmSeed, BULK_BYTECODE, innerSeed, INNER_BYTECODE)
  var scan = vm.scan(vm.bulk)
  check('jsvmp-bulk-integrity', scan.bad === 0 && scan.ops === Math.floor(BULK_BYTECODE.length / 3), 'ops=' + scan.ops + ' maxDepth=' + scan.maxDepth + ' checksum=' + (scan.checksum >>> 0).toString(16))
  check('jsvmp-bulk-histogram', (scan.histogram[1] || 0) > 0 && (scan.histogram[4] || 0) > 0, 'push=' + (scan.histogram[1] || 0) + ' add=' + (scan.histogram[4] || 0))

  var innerVm = new FortressVm(innerSeed, INNER_BYTECODE, 0, '')
  var innerProgram = innerVm.loadEncoded(INNER_BYTECODE, innerSeed)
  var innerValue = innerVm.run(innerProgram)
  check('jsvmp-inner-program', innerValue === 720, 'factorial(6)=' + innerValue)

  var programA = vm.assemble([
    ['push', 0],
    ['store', 1],
    ['push', 1],
    ['store', 0],
    ['label', 'loop'],
    ['load', 0],
    ['push', 21],
    ['lt'],
    ['jz', 'done'],
    ['load', 1],
    ['load', 0],
    ['load', 0],
    ['mul'],
    ['add'],
    ['store', 1],
    ['load', 0],
    ['push', 1],
    ['add'],
    ['store', 0],
    ['jmp', 'loop'],
    ['label', 'done'],
    ['load', 1],
    ['halt']
  ])
  var valueA = vm.run(programA)
  check('jsvmp-program-loop', valueA === 2870, 'sum-of-squares(1..20)=' + valueA)

  var programB = vm.assemble([
    ['push', 5],
    ['push', 7],
    ['mul'],
    ['call'],
    ['add'],
    ['halt']
  ])
  var valueB = vm.run(programB)
  check('jsvmp-vm-in-vm', valueB === 755, '35+factorial(6)=' + valueB)

  var programC = vm.assemble([
    ['loadk', 7],
    ['push', 3],
    ['mul'],
    ['halt']
  ])
  var valueC = vm.run(programC)
  check('jsvmp-const-pool', valueC === Math.imul(vm.consts[7] | 0, 3), 'const[7]=' + (vm.consts[7] | 0) + ' pool=512B')
  check('jsvmp-stack-integrity', vm.faults === 0 && innerVm.faults === 0 && vm.shadow !== 0, 'faults=0 shadow=' + (vm.shadow >>> 0).toString(16))

  var bootstrap = flattenedBootstrap(BUILD_SEED, probes.length)
  check('flattened-bootstrap', bootstrap.steps >= 5 && bootstrap.dead === 0, 'steps=' + bootstrap.steps + ' key=' + (bootstrap.key >>> 0).toString(16))

  var antiDebug = antiDebugSuite()
  var antiOk = 0
  for (var a = 0; a < antiDebug.length; a++) {
    if (antiDebug[a].ok) antiOk++
    check('anti-debug-' + antiDebug[a].id, antiDebug[a].ok, antiDebug[a].detail)
  }

  var variants = decryptorVariants(POOL_LAYERS)
  var sample = hexToBytes(POOL.slice(0, 512))
  var expectedPlain = POOL_LAYERS.decode(sample)
  var matches = 0
  for (var v = 0; v < variants.length; v++) {
    var output = variants[v](hexToBytes(POOL.slice(0, 512)))
    if (equalBytes(output, expectedPlain)) matches++
  }
  check('polymorphic-decoders', matches === variants.length, matches + '/' + variants.length + ' variants agree')

  var registry = {
    'wb-spn': {
      type: 'whitebox',
      blockSize: 16,
      kind: 'wb-spn',
      make: function (seed) {
        return new WhiteboxSpn(SPN_MATERIAL, seed, SPN_ROUNDS)
      }
    },
    'wb-feistel': {
      type: 'whitebox',
      blockSize: 8,
      kind: 'wb-feistel',
      make: function (seed) {
        return new WhiteboxFeistel(FEISTEL_MATERIAL, seed, FEISTEL_ROUNDS)
      }
    },
    'wb-arx': {
      type: 'whitebox',
      blockSize: 16,
      kind: 'wb-arx',
      make: function (seed) {
        return new WhiteboxArx(ARX_MATERIAL, seed, ARX_ROUNDS)
      }
    },
    'cipher-spn': {
      type: 'cipher',
      blockSize: 16,
      kind: 'spn',
      make: function (seed) {
        return new SpnCipher(seed, 12)
      }
    },
    'cipher-feistel': {
      type: 'cipher',
      blockSize: 8,
      kind: 'feistel',
      make: function (seed) {
        return new FeistelCipher(seed, 16)
      }
    },
    'cipher-arx': {
      type: 'cipher',
      kind: 'arx',
      make: function (seed) {
        return new ArxCipher(seed, 8)
      }
    },
    'enc-radix64': {
      type: 'encoding',
      make: function (seed) {
        return new Radix64Codec(seed)
      }
    },
    'enc-glyph': {
      type: 'encoding',
      make: function (seed) {
        return new GlyphCodec(seed, 0xe000)
      }
    },
    'enc-bitlane': {
      type: 'encoding',
      make: function (seed) {
        var codec = new BitLaneCodec(seed)
        return {
          encode: function (bytes) {
            var framed = [(bytes.length >>> 8) & 255, bytes.length & 255].concat(codec.encode(bytes))
            return bytesToHex(framed)
          },
          decode: function (text) {
            var framed = hexToBytes(text)
            var declared = ((framed[0] & 255) << 8) | (framed[1] & 255)
            return codec.decode(framed.slice(2)).slice(0, declared)
          }
        }
      }
    }
  }

  var pipelines = []
  var pipelineSeeds = [mix32(BUILD_SEED, 20) ^ bootstrap.key, mix32(BUILD_SEED, 21) ^ bootstrap.key, mix32(BUILD_SEED, 22) ^ bootstrap.key]
  var pipelineRounds = 0
  var labels = []
  for (var p = 0; p < pipelineSeeds.length; p++) {
    var pipeline = new MixedPipeline(registry, {
      whitebox: ['wb-spn', 'wb-feistel', 'wb-arx'],
      ciphers: ['cipher-spn', 'cipher-feistel', 'cipher-arx'],
      encodings: ['enc-radix64', 'enc-glyph', 'enc-bitlane']
    }, pipelineSeeds[p])
    var sealed = pipeline.seal(vector)
    var opened = pipeline.open(sealed)
    check('mixed-pipeline-' + p, equalBytes(opened, vector), pipeline.label + ' token=' + sealed.length + ' chars')
    pipelineRounds += pipeline.rounds
    pipelines.push(pipeline)
    labels.push(pipeline.label)
  }
  check('mixed-pipeline-orders', labels[0] !== labels[1] || labels[1] !== labels[2], labels.join(' | '))

  var fingerprintBefore = codeFingerprint([POOL_LAYERS.decode, FortressVm.prototype.run, WhiteboxSpn.prototype.encryptBlock, MixedPipeline.prototype.seal])
  var fingerprintAfter = codeFingerprint([POOL_LAYERS.decode, FortressVm.prototype.run, WhiteboxSpn.prototype.encryptBlock, MixedPipeline.prototype.seal])
  check('code-fingerprint-stable', fingerprintBefore === fingerprintAfter, 'fingerprint=' + (fingerprintBefore >>> 0).toString(16))

  var ddaProbes = probes.filter(function (item) { return item.group === 'html-dda' })
  var ddaSignals = ddaProbes.filter(function (item) { return item.signal })
  check('document-all-executed', ddaProbes.length >= 5 && ddaSignals.length >= 5, 'probes=' + ddaProbes.length + ' signals=' + ddaSignals.length)
  check('probe-matrix', probes.length >= 50, 'probes=' + probes.length)

  METRICS.whitebox = 3
  METRICS.customCiphers = 3
  METRICS.encodings = 3
  METRICS.jsvmpOps = scan.ops + innerProgram.code.length + programA.code.length + programB.code.length
  METRICS.envChecks = probes.length
  METRICS.polymorphicVariants = variants.length
  METRICS.mixedRounds = pipelineRounds
  METRICS.documentAll = ddaSignals.length >= 5
  METRICS.antiDebug = antiOk

  return {
    context: context,
    probes: probes,
    variants: variants,
    pipelines: pipelines,
    registry: registry,
    vector: vector,
    vm: vm,
    scan: scan,
    innerProgram: innerProgram,
    whiteboxes: { spn: wbSpn, feistel: wbFeistel, arx: wbArx },
    ciphers: { spn: spn, feistel: feistel, arx: arx },
    encoders: { radix: radix, bitlane: bitlane, glyph: glyph },
    antiDebug: antiDebug,
    poolDigest: poolDigestValue,
    bootstrap: bootstrap,
    codeFingerprint: fingerprintBefore,
    startedAt: Date.now()
  }
}

function finishReport(label) {
  var failed = CHECKS.filter(function (item) { return !item.ok })
  var payload = {
    whitebox: METRICS.whitebox,
    customCiphers: METRICS.customCiphers,
    encodings: METRICS.encodings,
    jsvmpOps: METRICS.jsvmpOps,
    envChecks: METRICS.envChecks,
    polymorphicVariants: METRICS.polymorphicVariants,
    mixedRounds: METRICS.mixedRounds,
    documentAll: METRICS.documentAll === true,
    antiDebug: METRICS.antiDebug
  }
  say('MEGA REPORT ' + label + ' checks=' + (CHECKS.length - failed.length) + '/' + CHECKS.length + ' probes=' + METRICS.envChecks + ' variants=' + METRICS.polymorphicVariants)
  for (var i = 0; i < failed.length; i++) say('MEGA CHECK FAILED ' + failed[i].id + ' ' + failed[i].detail)
  if (failed.length > 0) throw new Error('selftest failed: ' + failed.map(function (item) { return item.id }).join(','))
  say('MEGA SELFTEST OK')
  say('MEGA METRICS ' + JSON.stringify(payload))
}

